  if (type_byte(ds, element, 10) && word_at(ds, (uint16_t)(unit + 8)) == 0) {
    opeu_battle_ai_hold(ds, event, element);
    return;
  }
  if (word_at(ds, (uint16_t)(unit + 6)) == 0 ||
      opeu_battle_ai_plan_low(ds, event, element) == 4 ||
      opeu_battle_ai_plan_high(ds, event, element) == 1) {
    opeu_battle_ai_enter_or_hold(ds, event, element);
    return;
  }
  if (unit == GARRISON)
    opeu_battle_ai_plan_unit(ds, event, element, (uint16_t)(sp - 14));
  else
    opeu_battle_ai_think(ds, event, element, (uint16_t)(sp - 14));
